import { createRef } from 'react'

export type TapCoordinates = {
	ax: number
	ay: number
}

export const globalTapRef = createRef<{ current: TapCoordinates }>()

if (!globalTapRef.current) {
	globalTapRef.current = { current: { ax: 0, ay: 0 } }
}

export const setGlobalTapCoordinates = (coordinates: TapCoordinates) => {
	if (globalTapRef.current) {
		globalTapRef.current.current = coordinates
	}
}

export const getGlobalTapCoordinates = (): TapCoordinates => {
	return globalTapRef.current?.current ?? { ax: 0, ay: 0 }
}
